package adminweb

// Testcases one by one (R6.2; new): a page per testcase where the input is
// uploaded or written and the output written, uploaded, left empty or
// generated by a reference solution in the sandbox; and a generator run in
// the sandbox that writes the inputs of new testcases. Generation runs are
// user tests of the test participation (prepare.go).

import (
	"errors"
	"fmt"
	"html/template"
	"strings"
	"unicode/utf8"

	"github.com/jackc/pgx/v5"

	"github.com/d4nd3r/contest-management-system-enchanced/internal/importer"
	"github.com/d4nd3r/contest-management-system-enchanced/internal/importer/pkg"
	"github.com/d4nd3r/contest-management-system-enchanced/internal/store/q"
)

// previewSize is how much of an input or output the testcase page shows.
const previewSize = 64 << 10

// maxTextField bounds a file written in a text area.
const maxTextField = 16 << 20

// testcaseData is the data of testcase.html.
type testcaseData struct {
	*Page
	Task     *q.Task
	Dataset  *q.Dataset
	Judged   bool
	Testcase *q.Testcase // nil: a new testcase
	Input    filePreview
	Output   filePreview
	// Solutions are the test submissions that can generate outputs.
	Solutions []solutionChoice
	Pending   []pendingView
}

// filePreview is the beginning of a file as text.
type filePreview struct {
	Text      string
	Truncated bool
	Binary    bool
	Empty     bool
}

// solutionChoice is a test submission offered as reference solution.
type solutionChoice struct {
	ID       int32
	Name     string
	Selected bool
}

func (s *Server) preview(c *Ctx, digest string) filePreview {
	if digest == emptyDigest {
		return filePreview{Empty: true}
	}
	data, trunc, err := s.readBlob(c, digest, previewSize)
	if err != nil {
		return filePreview{Text: err.Error()}
	}
	if !utf8.Valid(data) && !trunc {
		return filePreview{Binary: true}
	}
	return filePreview{Text: strings.ToValidUTF8(string(data), "�"), Truncated: trunc}
}

// solutionChoices lists the test submissions of the task, the newest
// expected to be accepted first selected.
func (s *Server) solutionChoices(c *Ctx, t *q.Task, ds *q.Dataset) ([]solutionChoice, error) {
	uid, err := s.prepUserID(c.Context())
	if err != nil || uid == 0 {
		return nil, err
	}
	rows, err := s.st.Q.AdminPrepSubmissions(c.Context(), q.AdminPrepSubmissionsParams{DatasetID: ds.ID, TaskID: t.ID, UserID: uid, MaxRows: maxTestSubmissions})
	if err != nil {
		return nil, err
	}
	var out []solutionChoice
	chosen := false
	for _, r := range rows {
		name, _ := strings.CutPrefix(r.Comment, testCommentPrefix)
		ch := solutionChoice{ID: r.ID, Name: fmt.Sprintf("%d: %s", r.ID, name)}
		if !chosen && expectedVerdict(name) == pkg.VerdictAccepted {
			ch.Selected, chosen = true, true
		}
		out = append(out, ch)
	}
	return out, nil
}

// testcasePage is GET /dataset/<id>/testcase/<id> and GET
// /dataset/<id>/testcases/new.
func (s *Server) testcasePage(c *Ctx) {
	ds, t, ok := c.loadDataset(true)
	if !ok {
		return
	}
	d := testcaseData{Task: t, Dataset: ds, Judged: judgedDataset(t, ds)}
	if id, ok := c.PathID("testcase_id"); ok && c.R.PathValue("testcase_id") != "" {
		tc, err := s.st.Q.GetTestcase(c.Context(), id)
		if errors.Is(err, pgx.ErrNoRows) || err == nil && tc.DatasetID != ds.ID {
			c.NotFound()
			return
		}
		if err != nil {
			c.Fail(err)
			return
		}
		d.Testcase = &tc
		d.Input, d.Output = s.preview(c, tc.Input), s.preview(c, tc.Output)
	}
	var err error
	if d.Pending, err = s.collectGenerated(c, t, ds); err != nil {
		c.Fail(err)
		return
	}
	if d.Solutions, err = s.solutionChoices(c, t, ds); err != nil {
		c.Fail(err)
		return
	}
	if d.Page, err = c.Page(); err != nil {
		c.Fail(err)
		return
	}
	c.Render("testcase.html", d)
}

// fileFromForm reads one side of a testcase from the form: mode
// "upload" (the file field), "text" (the text area), "empty"; "" or
// "keep" leave it (ok false).
func (s *Server) fileFromForm(c *Ctx, side string) (digest string, ok bool, err error) {
	switch mode := c.ArgDefault(side+"_mode", "keep"); mode {
	case "upload":
		fh := c.File(side)
		if fh == nil {
			return "", false, fmt.Errorf("no %s file", side)
		}
		d, _, err := c.PutUpload(fh)
		return d, true, err
	case "text":
		text := c.R.FormValue(side + "_text")
		if len(text) > maxTextField {
			return "", false, fmt.Errorf("the %s is too long: upload it as a file", side)
		}
		text = strings.ReplaceAll(text, "\r\n", "\n")
		d, err := s.blobs.PutBytes(c.Context(), []byte(text))
		return d, true, err
	case "empty":
		d, err := s.blobs.PutBytes(c.Context(), nil)
		return d, true, err
	case "keep", "generate":
		return "", false, nil
	default:
		return "", false, fmt.Errorf("unknown mode %q", mode)
	}
}

// testcasePost is POST /dataset/<id>/testcase/<id> (change a testcase)
// and POST /dataset/<id>/testcases/new (create one).
func (s *Server) testcasePost(c *Ctx) {
	ds, t, ok := c.loadDataset(false)
	if !ok {
		return
	}
	var old *q.Testcase
	back := c.URL("dataset", ds.ID, "testcases", "new")
	if id, ok := c.PathID("testcase_id"); ok && c.R.PathValue("testcase_id") != "" {
		tc, err := s.st.Q.GetTestcase(c.Context(), id)
		if errors.Is(err, pgx.ErrNoRows) || err == nil && tc.DatasetID != ds.ID {
			c.NotFound()
			return
		}
		if err != nil {
			c.Fail(err)
			return
		}
		old = &tc
		back = c.URL("dataset", ds.ID, "testcase", tc.ID)
	}
	codename, _ := c.Arg("codename")
	if old != nil && codename == "" {
		codename = old.Codename
	}
	if !importer.ValidCodename(codename) {
		c.NotifyError(N("Invalid field(s)"), fmt.Sprintf("Invalid codename %q (letters, digits, _ and -).", codename))
		c.Redirect(back)
		return
	}
	_, public := c.Arg("public")
	in, inSet, err1 := s.fileFromForm(c, "input")
	out, outSet, err2 := s.fileFromForm(c, "output")
	if err := errors.Join(err1, err2); err != nil {
		c.NotifyError(N("Invalid field(s)"), err.Error())
		c.Redirect(back)
		return
	}
	if old == nil && !inSet {
		c.Notify(N("Invalid data"), N("Please give the input of the testcase."), nil)
		c.Redirect(back)
		return
	}
	generate := c.ArgDefault("output_mode", "keep") == "generate"
	var solutionID int32
	if generate {
		if v, ok := c.PathIDArg("solution"); ok {
			solutionID = v
		} else {
			c.Notify(N("Invalid data"), N("Choose the reference solution (a test submission) that generates the output."), nil)
			c.Redirect(back)
			return
		}
	}
	var tc q.Testcase
	var gens []pendingGen
	err := c.Write(func(tx *Tx) error {
		gens = nil
		p := q.AdminUpsertTestcaseParams{DatasetID: ds.ID, Codename: codename, Public: public, Input: in, Output: out}
		if old != nil {
			if !inSet {
				p.Input = old.Input
			}
			if !outSet {
				p.Output = old.Output
			}
		} else if !outSet {
			p.Output = emptyDigest
		}
		var err error
		if old != nil {
			tc, err = tx.Q.UpdateTestcase(tx.Ctx, q.UpdateTestcaseParams{ID: old.ID, Codename: codename, Public: public, Input: p.Input, Output: p.Output})
		} else {
			tc, err = tx.Q.CreateTestcase(tx.Ctx, q.CreateTestcaseParams(p))
		}
		if err != nil {
			return err
		}
		action := "testcase.create"
		if old != nil {
			action = "testcase.update"
		}
		if err := tx.Audit(AuditEntry{Action: action, TargetType: "dataset", TargetID: int64(ds.ID),
			ContestID: contestOf(t), Before: old, After: tc}); err != nil {
			return err
		}
		if generate {
			ut, err := s.generationRun(tx, t, solutionID, tc.Input)
			if err != nil {
				return err
			}
			gens = append(gens, pendingGen{Kind: genOutput, Codename: tc.Codename, UserTest: ut})
			return tx.Audit(AuditEntry{Action: "testcase.generate_output", TargetType: "dataset", TargetID: int64(ds.ID),
				ContestID: contestOf(t), Details: map[string]any{"testcase": tc.Codename, "solution": solutionID, "user_test": ut}})
		}
		return nil
	})
	if !c.Commit(err) {
		c.Redirect(back)
		return
	}
	if err := s.addPending(c.Context(), ds.ID, gens); err != nil {
		c.Fail(err)
		return
	}
	s.notifyUserTests(c.Context(), t, gens)
	s.notifyTask(c.Context(), t.ContestID, t.ID, ds.ID)
	c.Redirect(c.URL("dataset", ds.ID, "testcase", tc.ID))
}

// PathIDArg reads an id from a form argument.
func (c *Ctx) PathIDArg(name string) (int32, bool) {
	v, ok := c.Arg(name)
	if !ok {
		return 0, false
	}
	var n int32
	if _, err := fmt.Sscan(v, &n); err != nil || n <= 0 {
		return 0, false
	}
	return n, true
}

// generatorData is the data of generator.html.
type generatorData struct {
	*Page
	Task      *q.Task
	Dataset   *q.Dataset
	Judged    bool
	Solutions []solutionChoice
	Pending   []pendingView
	Example   template.HTML
}

// generatorPage is GET /dataset/<id>/generator.
func (s *Server) generatorPage(c *Ctx) {
	ds, t, ok := c.loadDataset(true)
	if !ok {
		return
	}
	d := generatorData{Task: t, Dataset: ds, Judged: judgedDataset(t, ds)}
	var err error
	if d.Pending, err = s.collectGenerated(c, t, ds); err != nil {
		c.Fail(err)
		return
	}
	if d.Solutions, err = s.solutionChoices(c, t, ds); err != nil {
		c.Fail(err)
		return
	}
	if d.Page, err = c.Page(); err != nil {
		c.Fail(err)
		return
	}
	c.Render("generator.html", d)
}

// maxGeneratorLines bounds the inputs generated by one request.
const maxGeneratorLines = 500

// generatorPost is POST /dataset/<id>/generator: the generator (a source
// in a language of the installation, run like a contestant's program of
// the task: it reads the line's arguments on its input and its output
// becomes the testcase's input) runs once per line "<codename>
// <arguments>"; with a reference solution the outputs are generated next.
func (s *Server) generatorPost(c *Ctx) {
	ds, t, ok := c.loadDataset(false)
	if !ok {
		return
	}
	back := c.URL("dataset", ds.ID, "generator")
	fh := c.File("generator")
	if fh == nil {
		c.Notify(N("Invalid data"), N("Please choose the generator."), nil)
		c.Redirect(back)
		return
	}
	data, ok, err := ReadUpload(fh, maxSolutionSize)
	if err != nil {
		c.Fail(err)
		return
	}
	if !ok {
		c.NotifyError(N("Invalid field(s)"), "the generator is too large")
		c.Redirect(back)
		return
	}
	sol, err := s.solutionFiles(t, fh.Filename, data)
	if err != nil {
		c.NotifyError(N("Invalid field(s)"), err.Error())
		c.Redirect(back)
		return
	}
	type line struct{ codename, args string }
	var lines []line
	for _, l := range strings.Split(strings.ReplaceAll(c.R.FormValue("lines"), "\r\n", "\n"), "\n") {
		l = strings.TrimSpace(l)
		if l == "" || strings.HasPrefix(l, "#") {
			continue
		}
		codename, args, _ := strings.Cut(l, " ")
		if !importer.ValidCodename(codename) {
			c.NotifyError(N("Invalid field(s)"), fmt.Sprintf("Invalid codename %q (letters, digits, _ and -).", codename))
			c.Redirect(back)
			return
		}
		lines = append(lines, line{codename, strings.TrimSpace(args) + "\n"})
	}
	if len(lines) == 0 || len(lines) > maxGeneratorLines {
		c.NotifyError(N("Invalid field(s)"), fmt.Sprintf("Write between 1 and %d lines.", maxGeneratorLines))
		c.Redirect(back)
		return
	}
	_, public := c.Arg("public")
	solutionID, _ := c.PathIDArg("solution")
	ctx := c.Context()
	var files []q.File
	for codename, b := range sol.Files {
		d, err := s.blobs.PutBytes(ctx, b)
		if err != nil {
			c.Fail(err)
			return
		}
		files = append(files, q.File{Filename: codename, Digest: d})
	}
	inputs := make([]string, len(lines))
	for i, l := range lines {
		if inputs[i], err = s.blobs.PutBytes(ctx, []byte(l.args)); err != nil {
			c.Fail(err)
			return
		}
	}
	var gens []pendingGen
	err = c.Write(func(tx *Tx) error {
		gens = nil
		if t.ContestID == nil {
			return errNoContest
		}
		for i, l := range lines {
			ut, err := s.createRun(tx, t, sol.Language, files, inputs[i])
			if err != nil {
				return err
			}
			gens = append(gens, pendingGen{Kind: genInput, Codename: l.codename, UserTest: ut, Public: public, Solution: solutionID})
		}
		return tx.Audit(AuditEntry{Action: "testcase.generate_inputs", TargetType: "dataset", TargetID: int64(ds.ID),
			ContestID: contestOf(t), Details: map[string]any{"generator": fh.Filename, "testcases": len(lines), "solution": solutionID}})
	})
	if !c.Commit(err) {
		c.Redirect(back)
		return
	}
	if err := s.addPending(ctx, ds.ID, gens); err != nil {
		c.Fail(err)
		return
	}
	s.notifyUserTests(ctx, t, gens)
	c.Redirect(back)
}
